query:
-- Remover duplicatas com empresaSlug em minúsculas (as corretas são em maiúsculas)
DELETE FROM categorias WHERE empresaSlug = 'mascote' AND tenantId = 1 AND ordem >= 6;
DELETE FROM categorias WHERE empresaSlug = 'morumbi' AND tenantId = 1 AND ordem >= 6;

-- Verificar resultado final
SELECT empresaSlug, nome, ordem FROM categorias WHERE tenantId = 1 AND empresaSlug IN ('MASCOTE', 'MORUMBI') ORDER BY empresaSlug, ordem;

